#ifndef APRS_COMPRESS_MODEL_H_
#define APRS_COMPRESS_MODEL_H_

#include <stdint.h>

// Static order-3 model tables. The definitions live in AprsCompressModel.cpp, which is
// generated by tools/aprs_compress/train_model.py (do not edit by hand).

namespace AprsCompressModel {

    constexpr uint32_t ORDER = 3;

    struct OrderTable {
        uint32_t         numContexts;
        const uint8_t*   keys;       // 3 bytes per context, sorted; the preceding bytes packed big-endian (order 0: key 0)
        const uint16_t*  offsets;    // numContexts + 1 entries into SYMBOLS / COUNTS
    };

    extern const uint8_t    VERSION;
    extern const OrderTable ORDERS[ORDER + 1];
    extern const uint8_t    SYMBOLS[];
    extern const uint8_t    COUNTS[];
}

#endif
